INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Tabelle in einer Datenbank immer nur eine Beziehung zu einer anderen hat?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Tabelle kann mehrere Beziehungen haben"}, {"text": "Ja", "correct": false, "because": "Mehrere Fremdschlüssel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie wird eine Tabelle in einer Datenbank formal genannt?', 3, '[{"text": "Relation", "correct": true, "because": "Mathematischer Begriff für Tabelle"}, {"text": "Entität", "correct": false, "because": "Bezieht sich auf Objekte"}, {"text": "Index", "correct": false, "because": "Für Abfrageoptimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren eine Tabelle in einer Datenbank?', 5, '[{"text": "Eindeutige Zeilen", "correct": true, "because": "Keine Duplikate erlaubt"}, {"text": "Definierte Spalten", "correct": true, "because": "Festgelegte Attribute"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Kein Kriterium"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Nur visuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Jede Zeile einer Tabelle ist ein Tupel. b) Spalten sind immer numerisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Spalten haben verschiedene Typen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition einer Tabelle?', 4, '[{"text": "Schlüsselbeziehungen", "correct": false, "because": "Sichern Integrität"}, {"text": "Datentypen", "correct": false, "because": "Definieren Spalten"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Tabelle ohne Schlüssel sinnvoll ist?', 2, '[{"text": "Nein", "correct": true, "because": "Schlüssel sichern Eindeutigkeit"}, {"text": "Ja", "correct": false, "because": "Schlüssel sind empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept verbindet Tabellen miteinander?', 4, '[{"text": "Fremdschlüssel", "correct": true, "because": "Verweist auf Primärschlüssel"}, {"text": "Trigger", "correct": false, "because": "Für Aktionen, nicht Verknüpfung"}, {"text": "View", "correct": false, "because": "Virtuelle Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Tabelle immer normalisiert sein muss. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Normalisierung ist optional"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle Zeilen in einer Tabelle eindeutig?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Duplikate laut Modell"}, {"text": "Nein", "correct": false, "because": "Eindeutigkeit erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Tabelle konsistent?', 5, '[{"text": "Primärschlüssel", "correct": true, "because": "Garantiert Eindeutigkeit"}, {"text": "Fremdschlüssel", "correct": true, "because": "Sichert Beziehungen"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Kein Konsistenzfaktor"}, {"text": "Viele Indizes", "correct": false, "because": "Für Leistung, nicht Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Gestaltung einer Tabelle?', 4, '[{"text": "Eindeutige Identifikation", "correct": true, "because": "Sichert Datenintegrität"}, {"text": "Maximale Spalten", "correct": false, "because": "Komplexität erhöht"}, {"text": "Bunte Visuals", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Spalten heißen Attribute. b) Jede Tabelle braucht mehrere Attribute.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ein Attribut reicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine funktionale Tabelle?', 3, '[{"text": "Definierte Spalten", "correct": false, "because": "Bestimmen Struktur"}, {"text": "Datentypen", "correct": false, "because": "Sichern Korrektheit"}, {"text": "Diagrammgestaltung", "correct": true, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Tabellen miteinander verknüpfe?', 4, '[{"text": "Fremdschlüssel einrichten", "correct": true, "because": "Verbindet Tabellen"}, {"text": "Nur Joins nutzen", "correct": false, "because": "Abfrage, keine Struktur"}, {"text": "Tabellen kopieren", "correct": false, "because": "Keine Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Tabellen immer viele Zeilen haben müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch leere Tabellen gültig"}, {"text": "Ja", "correct": false, "because": "Zeilenanzahl irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip sichert die Eindeutigkeit von Zeilen?', 3, '[{"text": "Primärschlüssel", "correct": true, "because": "Garantiert Einzigartigkeit"}, {"text": "Spaltenanzahl", "correct": false, "because": "Kein Eindeutigkeitsfaktor"}, {"text": "Tabellenname", "correct": false, "because": "Nur Bezeichnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Tabelle mehrere Fremdschlüssel haben?', 2, '[{"text": "Ja", "correct": true, "because": "Verknüpfung zu mehreren Tabellen"}, {"text": "Nein", "correct": false, "because": "Mehrere erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gut gestaltete Tabelle?', 5, '[{"text": "Konsistente Daten", "correct": true, "because": "Schlüssel sichern Integrität"}, {"text": "Effiziente Abfragen", "correct": true, "because": "Struktur unterstützt"}, {"text": "Viele Duplikate", "correct": false, "because": "Gegenteil von gut"}, {"text": "Bunte Visuals", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Tabellenstruktur unwichtig?', 3, '[{"text": "Spaltendefinition", "correct": false, "because": "Bestimmt Datenart"}, {"text": "Schlüssel", "correct": false, "because": "Sichern Beziehungen"}, {"text": "Spaltenreihenfolge", "correct": true, "because": "Kein logischer Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine Tabelle für Kundenbeziehungen erstelle?', 4, '[{"text": "Primär- und Fremdschlüssel definieren", "correct": true, "because": "Sichert Struktur"}, {"text": "Nur Spalten anlegen", "correct": false, "because": "Fehlt Beziehung"}, {"text": "Farben wählen", "correct": false, "because": "Irrelevant"}]');
